using OcctSharp.ConstructionWorkspaces;
using OcctSharp.Tests.Shared;
using OcctSharp.TopologyAssembly;
namespace OcctSharp.Runtime.Tests;
public sealed class ParameterizedConstructionTests {
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void AnalyticCurveSamplesAndCopiesAreIndependent(int kind){using var result=ParameterizedConstruction.AnalyticEdge((AnalyticConstructionCurve)kind,ConstructionFrame.World,0,.8,2,1);Assert.True(result.IsDone);using var shape=result.CopyShape();Assert.Equal(ShapeKind.Edge,shape.Kind);Assert.True(shape.IsValid);var p=result.Evaluate(.4);Assert.True(double.IsFinite(p.X)&&double.IsFinite(p.Y));var bounds=result.NativeBounds!;Assert.True(bounds.First<bounds.Last);result.Dispose();Assert.True(shape.IsValid);Assert.Throws<ObjectDisposedException>(()=>result.Evaluate(.4));Assert.NotNull(result.NativeBounds);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void AnalyticFaceNativeBoundsAndGeometryAreCopied(int kind){using var result=ParameterizedConstruction.AnalyticFace((AnalyticConstructionSurface)kind,ConstructionFrame.World,0,.8,.1,.5,3,.4);Assert.True(result.IsDone);Assert.True(result.IsFace);using var face=result.CopyShape();Assert.Equal(ShapeKind.Face,face.Kind);Assert.True(face.IsValid);var p=result.Evaluate(.4,.3);Assert.True(double.IsFinite(p.X)&&double.IsFinite(p.Y)&&double.IsFinite(p.Z));Assert.Null(result.CopyRelated(1));Assert.False(result.HasStoredPCurve);result.Dispose();Assert.True(face.IsValid);}
 [Fact]public void ReversedLineRetainsNativeDirectionAndFiniteRange(){using var result=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,ConstructionFrame.World,3,1);Assert.True(result.IsDone);Assert.Equal(0,result.NativeOrientation);Assert.Equal(1,result.NativeBounds!.First,8);Assert.Equal(3,result.NativeBounds.Last,8);Assert.Equal(2,result.Evaluate(2).X,8);Assert.Throws<ArgumentException>(()=>result.Evaluate(0));}
 [Fact]public void FullCirclePreservesClosedSeam(){using var result=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Circle,ConstructionFrame.World,0,2*Math.PI,2);using var shape=result.CopyShape();Assert.True(shape.IsValid);Assert.True(result.HasSharedEndpointVertex);Assert.Equal(2,shape.CountSubShapes(ShapeKind.Vertex));var a=result.Evaluate(result.NativeBounds!.First);var b=result.Evaluate(result.NativeBounds.Last);Assert.True(BatchBHIntersectionWorkflow.Distance(a.X,a.Y,a.Z,b.X,b.Y,b.Z)<1e-8);}
 [Fact]public void CurvePointAndVertexEndpointsProduceIndependentResults(){using var fixture=new BatchBLConstructionWorkflow.PCurveFixture();var a=BatchBLConstructionWorkflow.Point(fixture.Curve,.5);var b=BatchBLConstructionWorkflow.Point(fixture.Curve,1.5);using var first=TopologyAssembler.Vertex(a.X,a.Y,a.Z);using var last=TopologyAssembler.Vertex(b.X,b.Y,b.Z);using var points=ParameterizedConstruction.CurveEdge(fixture.Curve,a,b,.5,1.5);using var vertices=ParameterizedConstruction.CurveEdgeWithVertices(fixture.Curve,first,last,.5,1.5);Assert.True(points.IsDone);Assert.True(vertices.IsDone);using var copied=vertices.CopyShape();fixture.Dispose();first.Dispose();last.Dispose();vertices.Dispose();Assert.True(copied.IsValid);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void PcurveConstructorsRetainStoredRepresentationAndCoupledSamples(int mode){using var f=new BatchBLConstructionWorkflow.PCurveFixture();var a=BatchBLConstructionWorkflow.Point(f.Curve,.5);var b=BatchBLConstructionWorkflow.Point(f.Curve,1.5);using var va=TopologyAssembler.Vertex(a.X,a.Y,a.Z);using var vb=TopologyAssembler.Vertex(b.X,b.Y,b.Z);using var result=mode==0?ParameterizedConstruction.PCurveEdge(f.PCurve,f.Surface,.5,1.5):mode==1?ParameterizedConstruction.PCurveEdge(f.PCurve,f.Surface,a,b,.5,1.5):ParameterizedConstruction.PCurveEdgeWithVertices(f.PCurve,f.Surface,va,vb,.5,1.5);Assert.True(result.IsDone);Assert.True(result.HasStoredPCurve);foreach(double t in new[]{.6,.9,1.4}){var p=result.Evaluate(t);var sample=result.EvaluatePCurve(t);var uv=BatchBHIntersectionWorkflow.Eval(f.PCurve,t);Assert.Equal(uv.X,sample.UV.X,7);Assert.Equal(uv.Y,sample.UV.Y,7);Assert.True(BatchBHIntersectionWorkflow.Distance(p.X,p.Y,p.Z,sample.Point.X,sample.Point.Y,sample.Point.Z)<1e-6);}using var shape=result.CopyShape();f.Dispose();Assert.True(shape.IsValid);Assert.True(double.IsFinite(result.EvaluatePCurve(.9).Point.X));}
 [Fact]public void FailedEndpointConstructorPublishesOnlyNativeDiagnostics(){using var f=new BatchBLConstructionWorkflow.PCurveFixture();using var result=ParameterizedConstruction.CurveEdge(f.Curve,new(999,999,999),new(998,999,999),.5,1.5);Assert.False(result.IsDone);Assert.NotEqual(0,result.NativeErrorCode);Assert.Null(result.NativeBounds);Assert.Equal(-1,result.NativeOrientation);Assert.Throws<InvalidOperationException>(()=>result.CopyShape());Assert.Throws<InvalidOperationException>(()=>result.Evaluate(.8));}
 [Fact]public void InvalidFramesRangesEndpointTypesAndDisposedSourcesAreRejected(){Assert.Throws<ArgumentException>(()=>ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Circle,ConstructionFrame.World,0,1,-1));Assert.Throws<ArgumentException>(()=>ParameterizedConstruction.AnalyticFace(AnalyticConstructionSurface.Plane,ConstructionFrame.World,1,0,0,1));Assert.Throws<ArgumentException>(()=>ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,new(new(0,0,0),new(0,0,0),new(1,0,0)),0,1));Assert.Throws<ArgumentException>(()=>ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,new(new(0,0,0),new(0,0,1),new(0,0,1)),0,1));Assert.Throws<ArgumentException>(()=>ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,ConstructionFrame.World,0,double.PositiveInfinity));using var f=new BatchBLConstructionWorkflow.PCurveFixture();using var box=ShapeFactory.CreateBox(1,1,1);Assert.Throws<ArgumentException>(()=>ParameterizedConstruction.CurveEdgeWithVertices(f.Curve,box,box,.5,1.5));f.Curve.Dispose();Assert.Throws<ObjectDisposedException>(()=>ParameterizedConstruction.CurveEdge(f.Curve,new(0,0,0),new(1,1,1),0,1));}
 [Fact]public void CopiedCurveAndVertexResultsSurviveOwnerClosure(){using var result=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,ConstructionFrame.World,0,3);using var first=result.CopyRelated(1);using var last=result.CopyRelated(2);using var edge=result.CopyShape();result.Dispose();Assert.Equal(ShapeKind.Vertex,first!.Kind);Assert.Equal(ShapeKind.Vertex,last!.Kind);Assert.True(edge.IsValid);Assert.Throws<ObjectDisposedException>(()=>result.CopyRelated(1));}
 [Fact]public void ConcurrentQueryAndDisposeKeepCopiesValidOrRejectClosedOwner(){var result=ParameterizedConstruction.AnalyticEdge(AnalyticConstructionCurve.Line,ConstructionFrame.World,0,3);var copies=new System.Collections.Concurrent.ConcurrentBag<Shape>();Parallel.For(0,32,i=>{try{copies.Add(result.CopyShape());}catch(ObjectDisposedException){}if(i==5)result.Dispose();});result.Dispose();foreach(var copy in copies){Assert.True(copy.IsValid);copy.Dispose();}}
 [Fact]public void ReversedNonperiodicPcurveRetainsNativeReversedOrientation(){using var f=new BatchBLConstructionWorkflow.PCurveFixture(false);using var result=ParameterizedConstruction.PCurveEdge(f.PCurve,f.Surface,1.5,.5);Assert.True(result.IsDone);Assert.Equal(1,result.NativeOrientation);Assert.True(result.HasStoredPCurve);Assert.Equal(.5,result.NativeBounds!.First,8);Assert.Equal(1.5,result.NativeBounds.Last,8);using var edge=result.CopyShape();Assert.True(edge.IsValid);}
 [Fact]public void DescendingPeriodicPcurveRetainsNativeForwardSeamWrapping(){using var f=new BatchBLConstructionWorkflow.PCurveFixture();using var result=ParameterizedConstruction.PCurveEdge(f.PCurve,f.Surface,1.5,.5);Assert.True(result.IsDone);Assert.Equal(0,result.NativeOrientation);Assert.Equal(1.5,result.NativeBounds!.First,8);Assert.Equal(2*Math.PI+.5,result.NativeBounds.Last,8);Assert.True(result.HasStoredPCurve);using var edge=result.CopyShape();Assert.True(edge.IsValid);}
 [Fact]public void RealParameterizedTopologyAndStepIgesReadback()=>BatchBLConstructionWorkflow.Run();
}
